def common(x,ecog=False):
 for k,label in [('hypersensitivity','Hypersensitivity to a treatment component'),('pregnancy','Pregnancy'),('breastfeeding','Breastfeeding')]:
  x.inputs[k]=B(label);add(x,k.upper(),c(k,'==',True),'contraindicated',label+': do not administer; confirm the current source and specialist plan.',page=2 if x.code in ['00807','00894','00885'] else 3,section='Exclusions')
